one=np.ones_like(x)
mon={'1':one,'x':x,'v':v,'x2':x**2,'xv':x*v,'v2':v**2,'x3':x**3,'x2v':x**2*v,'xv2':x*v**2,'v3':v**3,'sinx':np.sin(x),'cosx':np.cos(x)}
def greedy(w,K=10):
    cand={}
    for k,m in mon.items():
        cand['c_'+k]=np.cos(w*t)*m
        cand['s_'+k]=np.sin(w*t)*m
        if k!='1': cand[k]=m
    cand['1']=one
    chosen=[]
    for it in range(K):
        best=None
        for k,col in cand.items():
            if k in chosen: continue
            F=np.array([cand[c] for c in chosen+[k]]).T
            c,_,_,_=np.linalg.lstsq(F,dv_dt,rcond=None)
            r=F@c-dv_dt
            s=np.sum(r**2)/np.sum((dv_dt-dv_dt.mean())**2)
            if best is None or s<best[0]: best=(s,k)
        chosen.append(best[1])
    return best[0],chosen
